"""Pending individually authored vsprintf display mechanisms, lines 1148–1686."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'관찰·디버깅','lib/vsprintf.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('Hex Buffer 출력·개수와 Separator','hex_string',
      '한 byte를 두 hex 문자로 출력할 때 입력 개수와 출력 폭이라는 이름이 어떻게 연결되는지 배웁니다.',
      'field_width=0이면 입력 pointer 검사도 하기 전에 바로 반환합니다. 기본 len은 1이고 양수 width는 min(width,64)개의 입력 byte를 뜻합니다. fmt의 C는 colon, D는 hyphen, N은 separator 없음, 그 외는 space입니다. 각 byte의 높은 nibble과 낮은 nibble을 출력하고 마지막 byte 뒤에는 separator를 넣지 않습니다.',
      'Width를 완성 문자열의 글자 수 대신 입력 byte 개수로 제공합니다. 유효 입력 길이를 보장하고 NUL 종료는 상위 출력 함수의 계약을 따릅니다. 이 함수의 64byte 제한을 다른 pointer formatter에도 동일하게 적용하지 않습니다.',
      '0의 조기 반환, 64 cap, 두 nibble, 마지막 separator 생략을 읽으세요.',
      [('width=2, 입력 0xab와 0x01, C suffix의 표시는?', 'ab:01이다','ab:01:이다','두 byte 각각 두 문자로 바꾸고 사이에만 colon을 넣습니다.'),
       ('양수 width=100이면 입력 byte를 몇 개까지 표시하는가?', '64개이다','100개를 반드시 모두 읽는다','min_t(int,field_width,64)가 입력 개수를 제한합니다. Caller는 선택된 개수만큼 유효 자료를 제공해야 합니다.')],
      [('Negative와 Zero','Negative width는 기본 1byte, 0은 아무 출력도 하지 않는 경로입니다. 둘을 같은 빈 출력 조건으로 생각하지 않습니다.'),
       ('논리적 출력 길이','buf<end일 때만 문자를 저장하되 buf는 계속 전진합니다. 공간이 충분했다면 나올 전체 길이와 실제 저장 부분을 구분합니다.')])
    lesson('Bitmap 표시·32bit Chunk와 연속 범위','bitmap_string',
      '같은 bit 집합을 hex 묶음이나 범위 목록으로 표시하는 두 방식의 자료 읽기 순서를 이해합니다.',
      'bitmap_string은 width를 bit 수로 받아 가장 높은 32bit chunk부터 내려갑니다. 첫 부분 chunk에는 필요한 bit mask와 ceil(bits/4) hex 폭을 사용하고 다음은 32bit씩 comma로 연결합니다. bitmap_list_string은 for_each_set_bitrange의 [rbot,rtop) 구간을 받아 한 bit면 rbot만, 연속이면 rbot부터 rtop-1까지 hyphen으로 표시합니다.',
      '유효 bitmap 저장공간과 의미 있는 bit 수를 제공합니다. Hex 표현의 높은 chunk 순서와 메모리 word 순서를 혼동하지 않습니다. 범위 iterator의 exclusive 끝을 그대로 출력하면 한 bit 더 표시하게 됩니다.',
      'CHUNKSZ=32, 첫 chunk mask, word/bit index, rtop-1을 읽으세요.',
      [('Set bit가 2,3,4,7이면 list 표시는?', '2-4,7이다','2-5,7-8이다','Iterator의 끝은 exclusive입니다. 출력에서는 rtop-1로 바꿔 마지막 set bit를 표시합니다.'),
       ('33bit hex 표시는 어느 chunk부터 시작하는가?', '최상위 1bit chunk부터 시작한다','가장 낮은 32bit chunk부터 시작한다','ALIGN(nr_bits,32)-32로 첫 위치를 정합니다. 첫 부분 chunk를 출력한 뒤 낮은 묶음으로 이동합니다.')],
      [('작은 자료구조','spec을 새 hex 설정으로 교체한 뒤 chunk 크기에 맞춰 field_width를 갱신합니다. 입력 width는 bit 수였지만 숫자 helper에 전달할 때는 hex 문자 폭이 됩니다.'),
       ('빈 집합','nr_bits=0이면 hex loop의 시작이 -32라 실행하지 않습니다. List도 set 구간이 없으면 아무 숫자도 표시하지 않습니다. 출력 종료 문자를 자체 추가하지 않습니다.')])
    lesson('MAC 표시·순서 반전과 구분자','mac_address_string',
      '6byte 주소의 저장 순서와 사람이 읽는 구분자 표현을 분리하여 이해합니다.',
      '입력 pointer를 확인한 뒤 6byte를 hex_byte_pack으로 임시 문자열에 저장합니다. R suffix는 addr[5-i]로 byte 순서를 반전하고 기본 colon을 사용합니다. F는 hyphen을 선택합니다. fmt[0]==M일 때만 byte 사이에 separator를 넣고 소문자 m 형태는 구분하지 않습니다. 내부 NUL 뒤 string_nocheck로 외부 출력합니다.',
      '6byte의 유효 자료를 제공하고 선택한 format의 대소문자·suffix를 확인합니다. R은 byte 배열 표시 순서 변경이지 각 byte bit 반전이 아닙니다. 이 helper는 NIC 설정이나 주소 변경을 수행하지 않습니다.',
      '6회 반복, addr[5-i], M 조건과 내부 NUL을 읽으세요.',
      [('01:02:03:04:05:06의 R 표시는?', '06:05:04:03:02:01이다','80:40:c0:20:a0:60이다','R은 byte의 순서를 반전합니다. Byte 안의 bit를 반전하는 알고리즘이 아닙니다.'),
       ('소문자 m의 기본 표시는?', '010203040506이다','언제나 colon이 들어간다','Separator를 저장하는 조건은 fmt[0]==M입니다. 소문자는 연속된 hex 문자입니다.')],
      [('고정 내부 Buffer','임시 배열은 colon으로 나눈 여섯 byte와 NUL을 담도록 sizeof 문자열로 계산합니다. 외부 string helper의 폭·precision·잘림은 별도 단계입니다.'),
       ('Nibble 변환','각 byte의 상위 4bit와 하위 4bit를 hex 문자로 바꿉니다. byte 순서, nibble 순서, 출력 separator는 서로 다른 선택입니다.')])
    lesson('IPv4 표시·Byte Order와 세 자리 Zero','ip4_string',
      'Network 자료를 출력할 때 endian과 선택 format이 octet 순서를 어떻게 바꾸는지 이해합니다.',
      '기본 n·b는 addr[0]부터, l은 addr[3]부터 역순, h는 선택 host endian에 따라 순서를 정합니다. 각 octet은 put_dec_trunc8로 역순 decimal을 만들고 다시 뒤집습니다. fmt[0]==i이면 각 octet을 세 자리로 앞 0을 채우며 I이면 필요한 자리만 표시합니다. Octet 사이 dot과 내부 NUL을 추가합니다.',
      '실제 자료의 byte order와 n·b·l·h format을 맞춥니다. Host order와 network order를 문자열의 endian이라고 뭉뚱그리지 않습니다. 낮은 수준 ip4_string의 buffer는 최대 IPv4 문자열과 NUL을 담도록 caller가 준비합니다.',
      'index·step의 CONFIG 선택, aligned temp, decimal 뒤집기와 dot을 읽으세요.',
      [('입력 byte 1,2,3,4를 I4l로 표시하면?', '4.3.2.1이다','1.2.3.4이다','l은 index=3,step=-1입니다. 저장 byte의 읽는 순서를 역순으로 정합니다.'),
       ('같은 입력을 i4n으로 표시하면?', '001.002.003.004이다','1.2.3.4만 가능하다','소문자 i는 각 octet을 세 자리로 채웁니다. 대문자 I와 표기 폭이 다릅니다.')],
      [('Zero octet 연결','put_dec_trunc8의 0 처리 계약을 이 함수가 사용합니다. 임시 배열은 정렬된 4byte여서 한 자리 반환일 때 두 byte 저장도 감당합니다.'),
       ('Wrapper','ip4_addr_string은 충분한 내부 배열을 잡아 이 함수로 만든 뒤 string_nocheck에 전달합니다. 내부 NUL과 최종 외부 buffer의 종료 계약은 별도입니다.')])
    lesson('IPv6 기본 표시·고정 Hex와 Colon','ip6_string',
      '128bit 주소를 byte 배열에서 읽어 출력할 때 16bit 묶음과 문자열 모드의 차이를 배웁니다.',
      '8회 반복에서 byte 두 개씩 hex_byte_pack으로 네 자리 hex를 만듭니다. 대문자 I이면 마지막 묶음을 제외하고 colon을 붙이며 소문자 i는 separator 없이 이어 붙입니다. 이 기본 함수는 모든 묶음의 선행 0을 유지하고 끝 NUL을 저장합니다. ip6_addr_string은 I와 c suffix 조합일 때만 별도 compressed 함수를 선택합니다.',
      '16byte 자료를 제공하고 고정 표현과 압축 표현을 구분합니다. 여기에는 길이 0 run 탐색이 없습니다. Network byte 순서의 두 byte를 그대로 hex로 변환하는 단계와 숫자를 host order로 변환하는 단계를 구분합니다.',
      '8묶음·두 byte pack·I separator와 c wrapper 선택을 읽으세요.',
      [('기본 I6에서 값 1인 묶음은?', '0001로 표시한다','언제나 1만 표시한다','기본 함수는 두 byte를 각각 두 자리 hex로 만듭니다. 선행 0 제거는 compressed 구현의 일입니다.'),
       ('소문자 i6 기본 표현에 colon이 있는가?', 'separator 없이 32 hex 문자이다','대문자와 같은 7개 colon이 있다','Colon 저장 조건은 fmt[0]==I입니다. Byte 자료 자체는 같은 순서로 읽습니다.')],
      [('대소문자 의미','Format의 I/i 구분은 주소 표현 모드입니다. 출력 hex 문자의 대소문자를 일반 숫자 SMALL flag로 선택하는 것과 다른 규칙입니다.'),
       ('내부 공간','Wrapper는 IPv4 tail을 포함할 수 있는 최대 IPv6 문자열 크기로 임시 공간을 잡습니다. 실제 출력 길이는 기본과 압축 선택에 따라 다릅니다.')])
    lesson('IPv6 압축·최장 Zero Run과 동률 처리','ip6_compressed_string',
      '주소 압축에서 연속된 0을 찾는 작은 알고리즘과 예외적인 IPv4 tail 표현을 배웁니다.',
      '자료를 local in6_addr로 복사하고 mapped 또는 ISATAP이면 첫 6묶음, 아니면 8묶음에서 각 시작의 연속 0 길이를 구합니다. 길이가 현재 longest보다 클 때만 위치를 바꾸므로 동률이면 앞쪽을 유지합니다. 한 묶음의 0은 압축하지 않습니다. 최장 구간은 ::로 바꾸고 나머지 16bit는 ntohs 뒤 선행 0 없이 hex로 만듭니다. IPv4 tail 모드에서는 마지막 4byte를 decimal 주소로 붙입니다.',
      'Network 저장 순서의 유효 16byte를 제공합니다. 전체 address 압축과 단일 0의 선행 0 생략을 구분합니다. 이 함수의 두 loop는 고정 최대 8묶음이며 임의 크기의 압축 자료구조 알고리즘으로 확대하지 않습니다.',
      'range=6/8, > 비교, longest=1, needcolon, IPv4 tail을 읽으세요.',
      [('같은 길이의 최장 0 구간이 둘이면?', '먼저 나타난 구간을 선택한다','나중 구간이 항상 덮어쓴다','업데이트 조건이 >입니다. 같은 길이에서는 colonpos가 바뀌지 않습니다.'),
       ('0인 묶음 한 개만 있으면 ::로 바꾸는가?', '단일 0은 압축하지 않는다','언제나 ::로 바꾼다','longest 초기값이 1이고 최종 longest==1이면 colonpos=-1입니다. 그 묶음은 문자 0으로 표시합니다.')],
      [('Endian','0 여부 비교는 byte 순서와 무관하지만 비zero 묶음의 수치 출력은 ntohs로 변환합니다. 같은 array에서 각 처리 목적의 endian 조건이 다를 수 있습니다.'),
       ('IPv4 Tail','Mapped·ISATAP 검사는 별도 header helper의 실제 조건과 연결됩니다. 모든 IPv6 주소가 마지막 4byte를 decimal로 표시하는 것은 아닙니다.')])
    lesson('Socket 주소 표시·Port Flow와 Scope','ip6_addr_string_sa',
      '주소 외의 port·flowinfo·scope 자료를 표시할 때 괄호와 단위 변환을 결합하는 원리를 배웁니다.',
      'IPv6 socket formatter는 alphabetic suffix를 읽어 p·f·s·c 선택을 모읍니다. Port·flow·scope 중 하나라도 있으면 주소를 대괄호로 감싸고 각각 colon·slash·percent로 값을 이어 붙입니다. Port는 ntohs, flowinfo는 network mask와 ntohl, scope_id는 원래 수치로 표시합니다. IPv4 socket helper는 선택 order와 p를 읽고 주소 뒤 port를 붙입니다.',
      'sockaddr 종류와 원하는 suffix를 맞추고 주소 byte order, port의 16bit network order, scope의 의미를 구분합니다. 내부 출력용 숫자 spec을 상위 호출 문맥과 연결합니다. 표시 함수가 실제 socket 연결이나 routing을 수행하는 것은 아닙니다.',
      'alphabetic suffix loop, 괄호 조건, ntohs·mask/ntohl·scope를 읽으세요.',
      [('IPv6 port만 추가해도 대괄호를 사용하는가?', '주소를 대괄호로 감싼 뒤 colon과 port를 붙인다','주소 묶음 사이에 port를 바로 이어 붙인다','IPv6 자체의 colon과 port separator를 구분하기 위해 주소 구간을 감쌉니다. have_p도 괄호 조건입니다.'),
       ('IPv6 scope_id에도 ntohs를 적용하는가?', '원래 수치를 직접 number에 전달한다','모든 필드를 16bit network 값으로 읽는다','Port·flowinfo·scope는 자료의 타입과 저장 계약이 다릅니다. Scope에는 별도의 ntohs가 없습니다.')],
      [('수집 후 고정 순서','Suffix가 어떤 순서로 등장해도 boolean 선택을 모은 뒤 port→flow→scope 순서로 출력합니다. Input suffix 순서가 그대로 결과 순서가 되는 구조가 아닙니다.'),
       ('압축 선택','IPv6 socket의 c는 대문자 I 모드에서 compressed 함수를 선택합니다. 소문자 i의 기본 표현 규칙과 분리하여 읽습니다.')])
    lesson('IP Formatter 분배·Family와 잘못된 Format','ip_addr_string',
      '공통 pointer formatter가 자료 타입에 맞는 구현으로 분배하고 모르는 타입을 처리하는 원리를 배웁니다.',
      'Pointer 사전 검사 후 fmt[1]이 6이면 IPv6, 4면 IPv4, S이면 sockaddr union의 sa_family를 읽습니다. AF_INET과 AF_INET6는 각각 socket helper로 분배하며 다른 family는 (einval)을 표시합니다. 알려진 selector가 아니면 소문자 i와 대문자 I에 맞는 질문형 오류 메시지를 반환합니다.',
      'Format과 실제 자료 타입을 맞춥니다. Sa_family를 읽을 수 있는 유효 sockaddr 저장공간을 제공합니다. Union의 모든 멤버가 동시에 유효하다고 생각하지 않고 family에 맞는 멤버만 읽습니다.',
      '4·6·S selector, union family, 두 오류 메시지 경로를 읽으세요.',
      [('S 선택인데 family가 AF_INET도 AF_INET6도 아니면?', '(einval)을 표시한다','자료를 무조건 IPv6로 읽는다','Family switch의 default가 error_string을 호출합니다. 임의 자료를 IPv6 주소처럼 출력하지 않습니다.'),
       ('자료는 IPv4인데 format으로 6을 전달하면 자동으로 수정되는가?', 'caller가 자료 타입과 format을 맞춰야 한다','이 함수가 자료 크기를 자동 검출한다','6은 해당 helper를 직접 선택합니다. 일반 pointer에서 실제 object 크기를 알아내는 코드가 없습니다.')],
      [('Tagged 선택','Union 자체에는 runtime active-member 표시가 없습니다. sa_family 필드가 어떤 자료 형식으로 읽을지를 정하는 외부 tag 역할을 합니다.'),
       ('검사 범위','check_pointer는 NULL·낮은 주소·error 표현을 분류합니다. 자료 길이·전체 mapping·객체 수명까지 증명하는 함수가 아니므로 분배 전제는 caller에 있습니다.')])
    lesson('Escape 출력·Flag 조합과 필요한 전체 길이','escaped_string',
      '이미 배운 escape engine이 출력 format과 연결될 때 flag 선택과 buffer 길이 회계가 어떻게 이어지는지 배웁니다.',
      'field_width=0이면 바로 반환합니다. Pointer 검사 뒤 suffix a·c·h·n·o·p·s를 각각 escape flag로 OR하여 모으고 모르는 문자에서 멈춥니다. 선택 flag가 없으면 ESCAPE_ANY_NP를 사용합니다. 입력 길이는 negative width이면 1, 그 외 width이며 string_escape_mem에 실제 남은 출력 공간을 전달하고 필요한 전체 출력 길이만큼 buf를 전진시킵니다.',
      '입력 byte 수와 유효 저장공간을 보장하며 flags 조합의 escape 우선순위는 engine 구현과 함께 읽습니다. Hex buffer helper의 64byte cap을 여기에도 있다고 가정하지 않습니다. 필요한 길이와 실제 저장량을 구분합니다.',
      'width 0, suffix OR, 기본 flags, 공간 0 전달과 반환 길이를 읽으세요.',
      [('출력 공간이 부족해도 buf는 어떤 길이만큼 전진하는가?', '공간이 충분했다면 필요한 전체 길이이다','저장한 byte 수만큼이다','string_escape_mem은 필요한 전체 출력 크기를 반환합니다. 이 helper는 그 반환을 buf에 더합니다.'),
       ('알려진 suffix flag가 하나도 없으면?', 'ESCAPE_ANY_NP를 선택한다','원본 byte를 무조건 그대로 복사한다','flags==0일 때 기본 escape 정책을 설정하는 branch가 있습니다.')],
      [('Zero 공간','buf>=end이면 engine에 출력 공간 0을 전달합니다. 자료를 저장하지 않아도 길이 계산에 입력 byte를 읽을 수 있으므로 입력 수명은 필요합니다.'),
       ('Engine 재사용','이 함수는 escape 규칙 전체를 새로 구현하지 않습니다. Format suffix를 기존 engine의 bitmask에 연결하는 adapter이며 실제 hex·octal 규칙은 해당 수업과 연결합니다.')])
    lesson('중첩 Va Format·Va Copy와 Owner 보존','va_format',
      '가변 인자 목록을 다른 formatter에 넘길 때 원래 목록의 상태를 보존하는 사용법을 배웁니다.',
      'va_format은 wrapper pointer를 확인하고 va_copy로 *va_fmt->va를 local va에 복제합니다. 복제한 목록을 vsnprintf에 전달하고 반환한 필요한 길이만큼 buf를 이동한 뒤 va_end로 복제 상태를 정리합니다. End가 buf보다 앞이나 같으면 공간 0을 전달합니다.',
      '유효한 format 문자열과 해당 format에 맞는 타입의 인자 목록을 제공합니다. Va_list를 단순 구조 대입으로 복사하지 않습니다. 소유 caller의 목록과 이 함수가 정리할 복제 목록을 구분합니다.',
      'pointer 검사→va_copy→vsnprintf→va_end를 읽으세요.',
      [('이 helper가 va_end로 정리하는 목록은?', 'va_copy로 만든 local 목록이다','caller가 소유한 원본 목록이다','복제 목록을 소비하고 정리합니다. 원본 목록의 소유권을 이 함수가 가져가는 구조가 아닙니다.'),
       ('출력 공간 0이면 길이 회계도 0으로 고정되는가?', 'vsnprintf의 필요한 길이를 계속 사용한다','공간이 없으면 항상 길이를 0으로 바꾼다','저장 가능량과 필요한 길이가 다릅니다. 원본은 반환값을 그대로 buf에 더합니다.')],
      [('ABI에 따른 Va List','va_list는 플랫폼마다 배열이나 여러 상태 필드를 포함할 수 있습니다. 전용 va_copy와 va_end 계약으로 복제·정리를 처리합니다.'),
       ('타입 계약','Format이 요구하는 타입과 가변 인자의 실제 타입이 맞아야 합니다. Va_copy는 잘못된 format·인자 조합을 검증하거나 자동 변환하는 기능이 아닙니다.')])
